checker.setup:
def _good(age):
    if age is None:
        return None
    if age < 35:
        return "16-34"
    if age < 55:
        return "35-54"
    return "55+"

def _off_by_one(age):
    if age is None:
        return None
    if age <= 35:
        return "16-34"
    if age <= 55:
        return "35-54"
    return "55+"

def _missing_to_old(age):
    if age is None or age >= 55:
        return "55+"
    if age < 35:
        return "16-34"
    return "35-54"

def _rows():
    marks = [m for m in getattr(test_age_band, "pytestmark", []) if m.name == "parametrize"]
    assert marks, "test_age_band has no parametrize mark"
    names, values = marks[0].args[0], marks[0].args[1]
    if isinstance(names, str):
        names = [n.strip() for n in names.split(",")]
    rows = []
    for value in values:
        value = getattr(value, "values", value)
        if not isinstance(value, (tuple, list)):
            value = (value,)
        rows.append(dict(zip(names, value)))
    return rows

def _failures():
    failed = 0
    for row in _rows():
        try:
            test_age_band(**row)
        except AssertionError:
            failed += 1
    return failed

